 const initialRequests=f.requests.length;assert.equal(canvases,0);assert.equal(f.$('#q-public-qr img'),null);f.$('[data-q-qr]').click();await waitFor(()=>f.$('#q-public-qr img'),'local QR PNG');
 const image=f.$('#q-public-qr img');assert.match(image.src,/^data:image\/png;base64,/);assert.equal(image.width,244);assert.equal(canvases,1);assert.match(image.alt,/问卷/);assert.doesNotMatch(f.root.textContent,/支付|付款|收银台/);assert.deepEqual(f.requests.slice(initialRequests).map(row=>row.path),['/auth/me','/auth/me']);
