test('maximum-length planning survives durable quote, reload, recovery and adoption of a thirty-kilobyte sixty-question result',async t=>{
 const f=await fixture(t),original=f.ctx.api,jobId='11111111-1111-4111-8111-111111111111';let quotes=0,submits=0,submitted,item;
 const title='题'.repeat(200),audience='人'.repeat(300),purpose='研'.repeat(2000),researchDimensions='维'.repeat(2000),analysisFocus='析'.repeat(2000);
 for(const [selector,value]of [['#writing-title',title],['#q-audience',audience],['#q-purpose',purpose],['#q-research-dimensions',researchDimensions],['#q-analysis-focus',analysisFocus],['#q-introduction','知'.repeat(2000)],['#q-count','60'],['#q-target-sample-size','1000']])f.input(selector,value);f.input('#q-scale-points','7','change');assert.equal(await f.handle.save(),true);const id=f.db.prepare('SELECT id FROM questionnaires').get().id;
 let output;for(let length=1;length<500;length++){const candidate={title,introduction:'a',questions:Array.from({length:60},(_,i)=>({id:'q'+(i+1),type:'text',title:'待核对问题 '+(i+1)+'研'.repeat(length),options:[],required:false}))},padding=30000-Buffer.byteLength(JSON.stringify(candidate));if(padding>=0&&padding<1999){candidate.introduction='a'.repeat(padding+1);output=candidate;break;}}
 assert.ok(output);assert.equal(Buffer.byteLength(JSON.stringify(output)),30000);
 f.ctx.api=async(path,data,options)=>{if(path==='/writing/capabilities')return{ready:true};if(path==='/writing/quote'){quotes++;return{token:'maximum-planning-quote',type:'agent',title:'问卷',source:'free',creditCost:0,expiresAt:new Date(Date.now()+60000).toISOString(),policyVersion:1};}if(path==='/writing/jobs'&&data){submits++;submitted=data.snapshot;item={id:jobId,kind:'questionnaire',operation:'questionnaire',status:'completed',completedUnits:4,totalUnits:4,output};return{item};}if(path==='/writing/jobs/'+jobId)return{item};return original(path,data,options);};
 f.$('[data-q-ai]').click();await waitFor(()=>f.$('[data-wj-consent]'),'all supported maximum planning fields must reach a durable quote');f.input('[data-wj-consent]',true,'change');f.$('[data-wj-start]').click();await waitFor(()=>f.$('[data-wj-apply]'));
 const stored=f.service.get(id,{id:'alice'}),beforeReload=stored.content;beforeReload.aiState.resumeFromJobId='44444444-4444-4444-8444-444444444444';assert.ok(Buffer.byteLength(JSON.stringify(beforeReload.aiState))<=20000);assert.equal(Object.hasOwn(beforeReload.aiState,'contextKey'),false);assert.equal(beforeReload.aiState.itemId,jobId);assert.equal(submitted.requirements.researchDimensions.length,2000);assert.equal(submitted.requirements.analysisFocus.length,2000);assert.equal((await f.service.handle({path:'/api/questionnaires/'+id,method:'POST',user:{id:'alice'},readBody:async()=>({version:stored.version,expectedUserId:'alice',content:beforeReload})})).status,200);
 disposeQuestionnaire();f.root.innerHTML='';f.dom.window.location.hash='tool/questionnaire?survey='+id;const reopened=mountQuestionnaire({container:f.root,ctx:f.ctx});await waitFor(()=>f.$('#q-research-dimensions')?.value.length===2000);f.$('[data-q-ai]').click();await waitFor(()=>f.$('[data-wj-apply]'));assert.equal(f.$('[data-wj-apply]').disabled,false,'restored immutable inputs must not drift');assert.equal(quotes,1);assert.equal(submits,1);
 f.$('[data-wj-apply]').click();await waitFor(()=>f.root.querySelectorAll('[data-q-question]').length===60);assert.equal(await reopened.save(),true);const adopted=f.service.get(id,{id:'alice'}).content;assert.equal(adopted.questions.length,60);assert.equal(adopted.title,title);assert.equal(adopted.audience,audience);assert.equal(adopted.purpose,purpose);assert.equal(adopted.targetSampleSize,1000);assert.equal(adopted.researchDimensions,researchDimensions);assert.equal(adopted.analysisFocus,analysisFocus);assert.equal(Object.hasOwn(adopted,'aiState'),false);assert.ok(Buffer.byteLength(JSON.stringify(adopted))<=60000);assert.equal(new Set(adopted.questions.map(q=>q.id)).size,60);assert.equal(quotes,1);assert.equal(submits,1);
});

test('an unchanged legacy questionnaire snapshot with a duplicated context key can recover and adopt without a new quote',async t=>{
 const f=await fixture(t),title='旧问卷快照兼容验收',audience='在校学生',purpose='比较数字阅读入口',oldSnapshot={title,profile:{level:'本科',major:'',language:'中文',targetWords:500},requirements:{outputCount:3,scalePoints:5,instructions:`目标人群：${audience}\n研究目标：${purpose}\n题数优先遵照上述研究目标中的要求，未指定时默认设计 6 道清楚、中性的匿名问题。不得索取姓名、电话、住址、证件、健康等敏感信息。`},materials:[],references:[],outline:[]},jobId='22222222-2222-4222-8222-222222222222';
 const created=await f.service.handle({path:'/api/questionnaires',method:'POST',user:{id:'alice'},readBody:async()=>({expectedUserId:'alice',content:{title,audience,purpose,introduction:'匿名自愿参与。',questionCount:3,scalePoints:5,questions:[],aiState:{ownerId:'alice',itemId:jobId,commandKey:'33333333-3333-4333-8333-333333333333',snapshot:oldSnapshot,contextKey:JSON.stringify(oldSnapshot)}}})}),id=created.value.item.id,original=f.ctx.api;let quotes=0,submits=0;
 f.ctx.api=async(path,data,options)=>{if(path==='/writing/jobs/'+jobId)return{item:{id:jobId,kind:'questionnaire',operation:'questionnaire',status:'completed',output:{title,introduction:'匿名自愿参与。',questions:Array.from({length:3},(_,i)=>({id:'q'+i,type:'text',title:'旧结果的问题 '+i,options:[],required:false}))}}};if(path==='/writing/quote'){quotes++;throw Error('recovery must not quote');}if(path==='/writing/jobs'&&data){submits++;throw Error('recovery must not resubmit');}return original(path,data,options);};
 disposeQuestionnaire();f.root.innerHTML='';f.dom.window.location.hash='tool/questionnaire?survey='+id;const reopened=mountQuestionnaire({container:f.root,ctx:f.ctx});await waitFor(()=>f.$('#writing-title')?.value===title);f.$('[data-q-ai]').click();await waitFor(()=>f.$('[data-wj-apply]'));assert.equal(f.$('[data-wj-apply]').disabled,false,'a deployment changing boilerplate cannot make unchanged user input stale');
 for(const [selector,changed,original]of [['#writing-title','修改后的主题',title],['#q-audience','不同人群',audience],['#q-purpose','不同研究目标',purpose],['#q-count','60','3'],['#q-scale-points','7','5'],['#q-target-sample-size','100',''],['#q-research-dimensions','新增研究维度',''],['#q-analysis-focus','新增分析重点','']]){f.input(selector,changed);f.$('[data-q-ai]').click();await waitFor(()=>f.$('.wf-notice')&&f.$('[data-wj-apply]')?.disabled,'changed user fields must invalidate legacy recovery');f.input(selector,original);f.$('[data-q-ai]').click();await waitFor(()=>f.$('[data-wj-apply]')&&!f.$('[data-wj-apply]').disabled,'restoring original user fields can reuse the same immutable result');}
 f.$('[data-wj-apply]').click();await waitFor(()=>f.root.querySelectorAll('[data-q-question]').length===3);assert.equal(await reopened.save(),true);assert.equal(f.service.get(id,{id:'alice'}).content.questions.length,3);assert.equal(quotes,0);assert.equal(submits,0);
});


